// Used for low-level conversions (e.g., byte manipulation)
int data = 100;
int* ptr_i = &data;
char* ptr_c;

// 1. Pointer type reinterpretation (low-level access)
// Cast int* to char*
ptr_c = reinterpret_cast<char*>(ptr_i);

// 2. Pointer <-> Integer address conversion
// (Requires std::uintptr_t from <cstdint>)
std::uintptr_t addr =
    reinterpret_cast<std::uintptr_t>(ptr_i);

// 3. Reconstruct the pointer from the address (Round-trip)
int* ptr_r =
    reinterpret_cast<int*>(addr);

// WARNING: Does not check size or alignment requirements.
// Dangerous if T* is cast to U* where U is larger than T.
